  const scope = { ...base };
  if (params.vehicle !== "global" && params.vehicle !== base.vehicleLine) {
    scope.vehicleLine = params.vehicle;
    scope.vehicleCode = VEHICLE_CODES[params.vehicle] ?? base.vehicleCode;
    delete scope.derivative;
  }
